/* loop2.mjs — ONE command that proves the STATIC toolchain, and that what it
 * recovers is the algorithm the live lab gate actually accepts.
 *
 *   [0] the original six-step runtime loop (tools/loop.mjs) must still pass
 *   [1] sample factory: javascript-obfuscator generates obfuscated variants of a
 *       plaintext signer we wrote (string array + rotation + flattening + dead
 *       code + mangled identifiers)
 *   [2] negative control: the plaintext key is NOT in the generated bytes, or the
 *       whole exercise is vacuous
 *   [3] static/ toolchain: sourcemap-first triage -> webcrack -> wakaru on the
 *       generated PAGE; assert the recovered source contains the key and the logic
 *   [4] same on a standalone signer whose key was invented by this run, then EXECUTE
 *       the recovered code in a sandbox and compare its output with node:crypto
 *       built independently from the known answer
 *   [5] same on a browserify-shaped bundle whose module carries transpiled `?.`/`??`
 *       — webcrack must unpack it and wakaru must put the syntax sugar back
 *   [6] run the recovered PAGE code with no browser and sign a fresh body with it:
 *       the live gate must answer 200 accepted, and a tampered signature 401
 *   [7] capture /obf-gen through CDP in a disposable Chrome and check the browser's
 *       own signature against the statically recovered key (static and runtime agree)
 *   [8] the surgical tooling on real recovered output: rename --list must still see
 *       the bindings that survived deobfuscation
 *   [9] negative control for the GRADER ITSELF: deobfuscate the same page asking
 *       for a key that is not in it; the toolchain must exit 4 and report the
 *       expect missing. A check that cannot fail proves nothing.
 *
 * Every step is the same tool an analyst would call by hand. Exit 0 proves the static
 * chain in this run; 6 means no generated known answer; 9 means a step was refuted.
 *
 *   node tools/loop2.mjs
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createServer, keyId } from '../lab/server.mjs';
import { loadRecovered, callGlobal } from '../static/lib/sandbox.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const STATIC = path.join(HERE, '..', 'static');
const ART = path.join(os.tmpdir(), 'web-reverse-captures', 'loop2');
fs.mkdirSync(ART, { recursive: true });

const steps = [];
const record = (label, pass, detail) => {
  steps.push({ label, pass, detail, ms: 0 });
  return pass;
};

function run(label, script, args, { expectStatus = 0, cwd = HERE, echo = true, timeoutMs = 180_000 } = {}) {
  const started = Date.now();
  return new Promise(resolve => {
    const child = spawn(process.execPath, [script, ...args], { cwd, encoding: 'utf8' });
    let out = '';
    child.stdout.on('data', d => out += d);
    child.stderr.on('data', d => out += d);
    const timer = setTimeout(() => { child.kill(); }, timeoutMs);
    child.on('close', code => {
      clearTimeout(timer);
      if (echo) console.log(`\n${'-'.repeat(78)}\n$ node ${path.relative(HERE, script).replace(/\\/g, '/')} ${args.join(' ')}\n${'-'.repeat(78)}\n${out.trimEnd()}`);
      const pass = code === expectStatus;
      steps.push({ label, pass, detail: pass ? `exit ${code}` : `expected exit ${expectStatus}, got ${code}`, ms: Date.now() - started });
      resolve({ code, out, pass });
    });
  });
}

const hmac = (key, message) => crypto.createHmac('sha256', key).update(message).digest('hex');

/* ------------------------------------------------------------------ the server */
const server = createServer({ log: () => {} });
await new Promise(r => server.listen(0, '127.0.0.1', r));
const origin = `http://127.0.0.1:${server.address().port}`;

console.log('web-reverse static toolchain loop');
console.log(`  server        ${origin} (in-process, loopback, binds port 0)`);
console.log(`  keyId         ${keyId()}`);
console.log(`  artifacts     ${ART}`);
console.log(`  toolchain     ${STATIC}`);

/* [0] — the runtime loop that already existed must not have been disturbed. */
await run('runtime loop (tools/loop.mjs, six steps) still passes', path.join(HERE, 'loop.mjs'), []);

/* [1] — sample factory. It generates INTO this run's artifact directory, so the
 *       known answer and the samples graded below are the same bytes, and the
 *       evidence trail is self-contained. */
const gen = await run('sample factory: javascript-obfuscator produces obfuscated variants',
  path.join(STATIC, 'gen-obf.mjs'), ['--json', '--out-dir', ART]);
let genReport = null;
try { genReport = JSON.parse(gen.out.slice(gen.out.indexOf('{'))); } catch { genReport = null; }
if (gen.pass && genReport) {
  const prot = genReport.variants.map(v => `${v.id}:${v.protections.families.length}`).join(' ');
  record('every variant carries string-array + flattening + dead code',
    genReport.variants.every(v => v.protections.missing.length === 0), prot);
} else {
  record('every variant carries string-array + flattening + dead code', false, 'sample factory did not report');
}

/* The known answer is read from the path the generator REPORTED it wrote, never
 * from a path re-derived here. That is the whole bug this file had: the two
 * sides agreed on a directory by coincidence, and the coincidence was false. */
if (!genReport || !genReport.manifest || !fs.existsSync(genReport.manifest)) {
  console.error(`loop2: the sample factory left no known answer at ${genReport ? genReport.manifest : '<no report>'}`);
  server.close();
  process.exit(6);
}
const known = JSON.parse(fs.readFileSync(genReport.manifest, 'utf8'));
const pageV = known.variants.find(v => v.id === 'page');
const signerV = known.variants.find(v => v.id === 'signer');
const bundleV = known.variants.find(v => v.id === 'bundle');

/* /obf-gen must serve THIS run's page, not a leftover from an earlier one.
   server.mjs resolves it per request, so setting it now is enough. */
process.env.WEB_REVERSE_GEN_PAGE = pageV.file;

/* [2] — negative control: nothing was handed to us in plaintext. */
{
  const leaks = known.variants.filter(v => fs.readFileSync(v.file, 'utf8').includes(v.key));
  record('negative control: no generated artifact contains its plaintext key', leaks.length === 0,
    leaks.length ? `leaked: ${leaks.map(v => v.id).join(',')}` : `${known.variants.length} artifact(s) checked`);
  record('negative control: generator key for the standalone variants is fresh this run',
    /^lab-static-(signer|bundle)-[0-9a-f]{16}-not-a-real-secret$/.test(signerV.key) && signerV.key !== bundleV.key,
    `signer ${signerV.key.slice(0, 26)}… / bundle …${bundleV.key.slice(-14)}`);
}

/* [3] — the page: HTML in, recovered signer out. */
const pageDeobf = await run('deobf /obf-gen page: key + logic recovered from obfuscated HTML',
  path.join(STATIC, 'deobf.mjs'),
  ['--in', pageV.file, '--artifacts', path.join(ART, 'page'),
    ...pageV.expects.flatMap(e => ['--expect', e])]);
const pageRecovered = path.join(ART, 'page', 'recovered.js');

/* [4] — a key this run invented, then executed back-to-back. */
const signerDeobf = await run('deobf standalone signer: fresh key recovered',
  path.join(STATIC, 'deobf.mjs'),
  ['--in', signerV.file, '--artifacts', path.join(ART, 'signer'),
    ...signerV.expects.flatMap(e => ['--expect', e])]);
{
  try {
    const code = fs.readFileSync(path.join(ART, 'signer', 'recovered.js'), 'utf8');
    const { sandbox, strippedEsm } = loadRecovered(code, { filename: 'recovered-signer.js' });
    const body = callGlobal(sandbox, signerV.buildEntry, ['lab.submit']);
    const ts = String(Date.now());
    const produced = callGlobal(sandbox, signerV.entry, [body, ts]);
    const independent = hmac(signerV.key, `${ts}.${body}`);
    const wrongKey = hmac(`${signerV.key}-x`, `${ts}.${body}`);
    const pass = produced === independent && produced !== wrongKey;
    record('recovered signer executes: its signature equals an independent node:crypto HMAC',
      pass, pass ? `${produced.slice(0, 16)}… (esm-strip ${strippedEsm})` : `got ${produced}, expected ${independent}`);
  } catch (e) {
    record('recovered signer executes: its signature equals an independent node:crypto HMAC', false, String(e.message).slice(0, 140));
  }
}

/* [5] — the bundle: unpack, then un-transpile. */
await run('deobf browserify bundle: unpacked, then `?.`/`??` restored by wakaru',
  path.join(STATIC, 'deobf.mjs'),
  ['--in', bundleV.file, '--artifacts', path.join(ART, 'bundle'),
    ...bundleV.expects.flatMap(e => ['--expect', e])]);

/* [6] — the recovered page code, run with no browser, against the live gate. */
{
  let body = null, ts = null, sig = null, detail = '';
  try {
    const code = fs.readFileSync(pageRecovered, 'utf8');
    const { sandbox } = loadRecovered(code, { filename: 'recovered-page.js' });
    body = callGlobal(sandbox, pageV.buildEntry, []);
    ts = String(Date.now());
    sig = callGlobal(sandbox, pageV.entry, [body, ts]);
    detail = `sandbox signed ${sig.slice(0, 16)}…`;
  } catch (e) {
    record('recovered page code signs a fresh body in a sandbox', false, String(e.message).slice(0, 140));
  }
  if (sig) {
    record('recovered page code signs a fresh body in a sandbox', true, detail);
    const post = async (signature, timestamp, payload) => {
      const res = await fetch(`${origin}/api/submit`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-lab-ts': timestamp, 'x-lab-sign': signature },
        body: payload
      });
      return { status: res.status, body: await res.json().catch(() => null) };
    };
    const good = await post(sig, ts, body);
    record('the live gate ACCEPTS the signature the recovered code produced',
      good.status === 200 && good.body?.accepted === true, `HTTP ${good.status} ${good.body?.error || 'accepted'}`);
    const bad = await post(hmac(`${pageV.key}-x`, `${ts}.${body}`), ts, body);
    record('negative control: a wrong-key signature is rejected', bad.status === 401, `HTTP ${bad.status} ${bad.body?.error || ''}`);
  }
}

/* [7] — runtime vs static: the browser's own signature must match the recovered key. */
{
  const captureFile = path.join(ART, 'obf-gen-capture.json');
  const cap = await run('capture /obf-gen through CDP (disposable Chrome)',
    path.join(HERE, 'capture.mjs'), ['--url', `${origin}/obf-gen`, '--clicks', '1', '--out', captureFile]);
  if (cap.pass) {
    try {
      const artifact = JSON.parse(fs.readFileSync(captureFile, 'utf8'));
      const hit = artifact.requests.find(r => r.status === 200 && r.headers['x-lab-sign']);
      const recovered = fs.readFileSync(pageRecovered, 'utf8');
      const keyIsInRecovered = recovered.includes(pageV.key);
      const reproduced = hit ? hmac(pageV.key, `${hit.headers['x-lab-ts']}.${hit.body}`) === hit.headers['x-lab-sign'] : false;
      record('recovered key reproduces the browser\'s captured signature',
        !!hit && keyIsInRecovered && reproduced,
        hit ? `ts=${hit.headers['x-lab-ts']} sign=${String(hit.headers['x-lab-sign']).slice(0, 16)}… reproduced=${reproduced}` : 'no accepted request captured');
    } catch (e) {
      record('recovered key reproduces the browser\'s captured signature', false, String(e.message).slice(0, 140));
    }
  } else {
    record('recovered key reproduces the browser\'s captured signature', false, 'capture failed');
  }
}

/* [8] — the surgical tooling, on real recovered output. */
{
  const r = await run('rename --list sees the remaining mangled bindings in the recovered file',
    path.join(STATIC, 'rename.mjs'), ['--in', pageRecovered, '--list', '--json']);
  try {
    const report = JSON.parse(r.out.slice(r.out.indexOf('{')));
    record('rename --list sees the remaining mangled bindings in the recovered file',
      r.pass && report.renameable >= 1, `${report.renameable} of ${report.bindings} binding(s) still mangled`);
  } catch {
    record('rename --list sees the remaining mangled bindings in the recovered file', false, 'no JSON report');
  }
}

/* [9] — NEGATIVE CONTROL for the deobfuscation assertion itself. Everything above
   can only be trusted if the grader is capable of failing. So: deobfuscate the
   very same page asking for a key that is NOT in it, and require the toolchain
   to reject the recovery (exit 4, `ok:false`, the expect reported missing).
   A key swapped by one character must flip the verdict, which is what separates
   "recovered the algorithm" from "substring matched". */
{
  const wrongKey = pageV.key.replace(/.$/, pageV.key.endsWith('1') ? '2' : '1');
  const neg = await run('negative control: deobf is asked for a key that is not in the file',
    path.join(STATIC, 'deobf.mjs'),
    ['--in', pageV.file, '--artifacts', path.join(ART, 'negative-control'),
      '--expect', wrongKey, '--expect', 'hmacSha256Hex'],
    { expectStatus: 4 });
  let report = null;
  try { report = JSON.parse(fs.readFileSync(path.join(ART, 'negative-control', 'deobf-report.json'), 'utf8')); } catch { report = null; }
  record('negative control: the same toolchain REJECTS a recovery graded against a wrong key',
    neg.code === 4 && report && report.ok === false
      && report.expects.missing.includes(wrongKey) && report.expects.missing.length === 1,
    report
      ? `exit ${neg.code}, ok=false — the one-character-mutated key was reported missing, `
        + `while the genuine expect (${report.expects.found}/${report.expects.requested.length}) still matched: `
        + `so the verdict tracks the key, not the file`
      : `exit ${neg.code}, no report`);
}

server.close();

/* ------------------------------------------------------------------ summary */
const failed = steps.filter(s => !s.pass);
console.log(`\n${'='.repeat(78)}\nweb-reverse static toolchain summary\n${'='.repeat(78)}`);
for (const s of steps) console.log(`  ${s.pass ? 'PASS' : 'FAIL'}  ${s.label.padEnd(62)} ${s.detail}${s.ms ? `  (${(s.ms / 1000).toFixed(1)}s)` : ''}`);
console.log(`\n${failed.length === 0
  ? 'STATIC TOOLCHAIN PROVEN: obfuscated sample generated, deobfuscated, recovery graded against a known answer, and the recovered code signed a request the live gate accepted.'
  : `${failed.length} step(s) failed`}`);
console.log(`artifacts: ${ART}`);
process.exit(failed.length === 0 ? 0 : 9);
